#!/bin/sh
# Code generated by AI (Claude Sonnet 5.5)

# Installs a package with the host package manager, a '-' name skips that package manager.
#
# Arguments:
#   $1  Package name for apt.
#   $2  Package name for dnf.
#   $3  Package name for pacman.
pkg_install() {
  if command -v apt-get >/dev/null 2>&1; then
    [ "$1" = "-" ] || { sudo apt-get update && sudo apt-get install -y "$1"; }
  elif command -v dnf >/dev/null 2>&1; then
    [ "$2" = "-" ] || sudo dnf install -y "$2"
  elif command -v pacman >/dev/null 2>&1; then
    [ "$3" = "-" ] || sudo pacman -S --needed --noconfirm "$3"
  else
    warn "no supported package manager (apt-get, dnf, pacman), install by hand: $1 (apt), $2 (dnf), $3 (pacman)"
  fi
}
